export function communityNoticeHTML(s,{E,esc,nearby=''}){
 const saved=s.neighborhoodDays.find(v=>v.day===s.day&&v.kind==='notice');
 return `<div class="modal-body neighborhood-desk"><p>Three invitations for an ordinary afternoon. Choose one to keep in your local daybook: <strong>free · 3 game minutes · 5 XP</strong>, once each day across all malls. Visiting a regular is optional and uses the normal walking route.</p><div class="neighborhood-notices">${E.COMMUNITY_NOTICES.map(n=>`<article class="notice-card ${saved?.choice===n.id?'selected':''}"><small>COMMUNITY NOTICE · ${esc(E.LOCALS.find(p=>p.id===n.person).name)}</small><h3>${esc(n.name)}</h3><p>${esc(n.text)}</p><button class="button ${saved?.choice===n.id?'orange':'secondary'} wide" data-action="notice-read" data-id="${n.id}" ${saved?'disabled':''}>${saved?.choice===n.id?'Kept in your daybook ✓':saved?'Choose another tomorrow':'Keep this invitation · 3 min'}</button><button class="text-button" data-action="local-visit" data-id="${n.person}">Walk over & say hello ↗</button></article>`).join('')}</div>${nearby}<button class="text-button" data-action="guest-services">Back to guest services</button></div>`;
}
export function lostPropertyHTML(s,{E,esc}){
 const done=s.neighborhoodDays.some(v=>v.day===s.day&&v.kind==='property'),c=E.lostPropertyCase(s.day);
 return `<div class="modal-body neighborhood-desk"><p>Help concierge match an original game prop to a visitor’s claim card. This never uses or adds a purchased product. <strong>Free · 6 game minutes · 15 XP</strong>, once each day across all malls. A wrong match costs nothing.</p>${done?'<div class="notice-card"><h3>A favorite found its way back.</h3><p>You helped with today’s claim. Another visitor may need a hand tomorrow.</p><span>Completed today ✓</span></div>':`<div class="property-claim"><small>VISITOR’S CLAIM · ${esc(c.reference)}</small><h3>“I remember ${esc(c.description.toLowerCase())}.”</h3><p>Choose the item that matches every detail.</p></div><div class="property-options">${c.options.map(v=>`<button data-action="property-match" data-id="${v.id}"><span aria-hidden="true">${v.emoji}</span><strong>${esc(v.name)}</strong><small>${esc(v.detail)}</small></button>`).join('')}</div>`}<button class="text-button" data-action="guest-services">Back to guest services</button></div>`;
}
export function homeRoutineHTML(s){const done=s.neighborhoodDays.some(v=>v.day===s.day&&v.kind==='unwind');return `<section class="home-routine"><div><small>A GENTLER WAY TO FINISH</small><h3>${done?'A quiet moment, kept.':'Put down the day for a moment.'}</h3><p>Unwind in your room for 8 game minutes. Recover up to 12 stamina and earn 10 XP, once each day. Leave enough time before closing.</p></div><button class="button secondary" data-action="home-unwind" ${done?'disabled':''}>${done?'Unwound today ✓':'Unwind · free · 8 min'}</button><button class="text-button" data-action="end-day">Ready to walk home & sleep ↗</button></section>`;}
